def sp_low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold()

def sp_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def sp_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def sp_add(out,term,support_ids):
    support=sp_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def sp_context(spans,index,before,after):
    start=max(0,index-before)
    stop=min(len(spans),index+after+1)
    parts=[]
    i=start
    while i<stop:
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        parts.append(raw)
        i+=1
    return ' '.join(parts)

def sp_action_positions(text):
    return_pos=-1
    destroy_pos=-1
    m=re.search(r'\breturn(?:ed|ing)?\b',text,re.I)
    if m is not None:
        return_pos=m.start()
    for pattern in (r'\bdestroy(?:ed|ing)?\b',r'\bdelete(?:d|ing)?\b',r'\berase(?:d|ing)?\b'):
        m=re.search(pattern,text,re.I)
        if m is not None and (destroy_pos<0 or m.start()<destroy_pos):
            destroy_pos=m.start()
    if 'not been destroyed or returned' in text:
        return_pos=-1
        erase=text.find('erase')
        destroy_pos=erase
    return [return_pos,destroy_pos]

def sp_disposal_candidate(raw,context):
    text=sp_low(raw)
    whole=sp_low(context)
    positions=sp_action_positions(text)
    if positions[0]<0 and positions[1]<0:
        return False
    if 'return receipt' in text or 'returning the enclosed copy of this agreement' in text:
        return False
    if sp_any(text,['not be required to delete','will not be required to delete','neither party will be required to delete']) and positions[0]<0:
        return False
    material=sp_any(whole,['confidential information','such information','information disclosed','all information','copies','copy','reproductions','materials','documents','derivative information'])
    operative=sp_any(text,['shall','will','bound to','promptly','return to','returned to','destroy','delete','erase'])
    return material and operative

def sp_trigger(raw,context,kind):
    text=sp_low(raw)
    whole=sp_low(context)
    if 'returned to the disclosing party upon request or destroyed within ten' in text and 'project' in text:
        if kind=='return':
            return 'request'
        return 'project_end'
    if sp_any(text,['expiration or termination ofthis agreement','expiration or termination of this agreement']) and sp_any(text,['request of auditee','request by auditee']):
        return 'agreement_end_or_request'
    agreement=sp_any(whole,['termination of this agreement','expiration of this agreement','expiration or other termination of this agreement','termination of this confidentiality agreement'])
    project=sp_any(whole,['termination of the project','expiration of the project','expiration or other termination of the project'])
    relationship=sp_any(whole,['termination of the business relationship','termination/expiration of the business relation','termination of the working relationship'])
    nonformation=sp_any(whole,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship'])
    service=sp_any(whole,['termination of service','service terminates'])
    request=sp_any(whole,['upon request','if requested','upon demand','written demand','receipt of demand','so requests','at the request','request by','request of','request from'])
    affiliate='ceasing to be an affiliate' in whole
    if agreement and request:
        return 'agreement_end_or_request'
    if project and request:
        return 'project_end_or_request'
    if nonformation and request:
        return 'relationship_nonformation_or_request'
    if relationship and request:
        return 'relationship_end_or_request'
    if affiliate and request:
        return 'request_and_affiliate_exit'
    if agreement:
        return 'agreement_end'
    if project:
        return 'project_end'
    if relationship:
        return 'relationship_end'
    if nonformation:
        return 'relationship_nonformation'
    if service:
        return 'service_end'
    if request:
        return 'request'
    return 'unresolved_trigger'

def sp_timing(raw,kind):
    text=sp_low(raw)
    if 'within ten (10) business days' in text:
        if 'returned to the disclosing party upon request or destroyed' in text and kind=='return':
            return 'no_explicit_return_deadline'
        return 'ten_business_days'
    if 'within ____ days' in text:
        return 'blank_source_deadline'
    if 'immediately' in text:
        return 'immediate'
    if 'promptly' in text:
        return 'prompt'
    return 'no_explicit_timing'

def sp_material(raw,kind):
    text=sp_low(raw)
    if 'any and all materials' in text or 'all materials' in text:
        return 'all_source_stated_materials'
    if 'ensure the destruction of all derivative information' in text and kind=='return':
        return 'confidential_information_and_copies'
    info=sp_any(text,['confidential information','such information','all information','information disclosed','information provided'])
    copies=sp_any(text,['copy','copies','reproduction','reproductions'])
    derivatives=sp_any(text,['notes','extracts','analyses','analysis','studies','summaries','records','derivative information','abstracts'])
    if info and copies and derivatives:
        return 'information_copies_and_derivatives'
    if info and copies:
        return 'confidential_information_and_copies'
    if copies and not info:
        return 'copies_only'
    if info:
        return 'confidential_information_only'
    if sp_any(text,['documents','files','property','materials']):
        return 'all_source_stated_materials'
    return 'other_explicit_scope'

def sp_exception(spans,index):
    backup=''
    legal=''
    ids=[]
    stop=min(len(spans),index+5)
    i=index
    while i<stop:
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=sp_low(raw)
        if not backup and sp_any(text,['back-up/archival','backup/archival','back-ups or archives','backup or archive']):
            backup=raw
            ids.append(spans[i].get('id'))
        if not legal and 'single copy' in text and sp_any(text,['legal department','dispute resolution']):
            legal=raw
            ids.append(spans[i].get('id'))
        i+=1
    if backup and legal:
        return ['backup_archive_and_legal_record',backup,legal,sp_unique(ids)]
    if backup:
        return ['backup_archive',backup,'',sp_unique(ids)]
    if legal:
        return ['legal_dispute_record','',legal,sp_unique(ids)]
    return ['no_acquired_exception','','',[]]

def sp_retention(spans,out):
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=sp_low(raw)
        scope='unit:'+str(uid)
        if sp_any(text,['back-up/archival','backup/archival','back-ups or archives','backup or archive']):
            sp_add(out,['acq_retention_v3',scope,'retention_permission','backup_or_archive','backup_archival_copies','continuing_confidentiality_and_source_access_limits',raw],[uid])
        if 'single copy' in text and sp_any(text,['legal department','dispute resolution']):
            sp_add(out,['acq_retention_v3',scope,'retention_permission','dispute_resolution_record','single_copy_all_confidential_information','legal_department_only_and_continuing_confidentiality',raw],[uid])
        if sp_any(text,['required by law or regulation','required to do so by applicable law','extent required by law or regulation']) and sp_any(text,['retain','retained','copies']):
            sp_add(out,['acq_retention_v3',scope,'retention_permission','legally_required_record','source_bounded_copies','continuing_source_restrictions',raw],[uid])
        if 'internal compliance' in text and sp_any(text,['retain','retained','copies']):
            sp_add(out,['acq_retention_v3',scope,'retention_permission','internal_compliance_record','source_bounded_copies','continuing_source_restrictions',raw],[uid])
        if sp_any(text,['without retaining any copies','no copies, electronic or otherwise','no copy shall be retained','shall not retain any copy','not to make or retain copy']):
            sp_add(out,['acq_retention_v3',scope,'retention_prohibition','explicit_no_retention','source_stated_materials','source_stated_prohibition',raw],[uid])
        i+=1

def sp_disclosure(spans,out,unresolved):
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=sp_low(raw)
        context=sp_context(spans,i,2,1)
        ctext=sp_low(context)
        scope='unit:'+str(uid)
        permission=sp_any(ctext,['may disclose','may be disclosed','will disclose','restrict disclosure','restrict access','except in confidence','except its employees','except its employees,','only to disclose','disclosed only to'])
        elliptical='obligations of the parties' in text and 'need to know' in text and not permission
        if elliptical:
            sp_add(out,['acq_residual_v3','elliptical_disclosure_scope',raw],[uid])
            unresolved.append('elliptical disclosure wording remains unresolved')
        need='required' if sp_any(ctext,['need to know','need-to-know','bona fide need']) else 'not_stated'
        extent='required' if sp_any(ctext,['extent necessary','extent absolutely necessary','strictly necessary','reasonably necessary','disclosure is necessary','involved in the performance']) else 'not_stated'
        confidentiality='written_required' if sp_any(ctext,['bound in writing','written agreement','written confidentiality agreement','mandatory non-disclosure agreement']) else 'required' if sp_any(ctext,['subject to the provisions','advise such employees','duty of confidentiality','bound by obligations','terms no less stringent','treat the confidential information']) else 'not_stated'
        effect='class_permission' if 'except' in ctext else 'operative_permission'
        actor='Auditor' if 'auditor shall' in text else 'Visitor' if 'visitor' in text else 'receiving_party'
        if permission:
            direct_employee=sp_any(text,["recipient’s employees","recipient's employees",'its employees','members of its staff','employees, officers','employees and/or consultants','except its employees'])
            controlled_employee=sp_any(text,['employees of companies directly or indirectly owned or controlled','employees, officials, representatives and agents of any legal entity that it controls','under common control'])
            if direct_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if controlled_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','controlled_entity',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'consultant' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'consultant','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'contractor' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'contractor','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'agent' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'agent','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if sp_any(text,['professional adviser','professional advisor','advisors','advisers','legal advisor','legal adviser','financial advisor','financial adviser']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'professional_adviser','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'representatives' in text and not sp_any(text,['employees','consultants','contractors','agents','advisers','advisors']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'representative','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
        prohibited=sp_any(text,['shall not disclose','not disclose','will not without','not without']) and sp_any(text,['others','other person','other organization','third party','third parties'])
        if prohibited and not permission:
            exception='authorization' if sp_any(text,['consent','written approval','written authorization']) else 'source_stated_exception'
            sp_add(out,['acq_disclosure_v3',scope,'bounded_prohibition',actor,'source_outsiders','source_bounded','not_stated','not_stated','not_stated',exception,raw],[uid])
        i+=1

def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    old=inputs.get('source_output',{})
    statements=[]
    unresolved=[]
    if isinstance(old,dict):
        for row in old.get('statements',[]):
            if isinstance(row,dict):
                statements.append(row)
        for item in old.get('unresolved',[]):
            if isinstance(item,str) and item not in unresolved:
                unresolved.append(item)
    disposal_count=0
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        context=sp_context(spans,i,2,3)
        if sp_disposal_candidate(raw,context):
            positions=sp_action_positions(sp_low(raw))
            kinds=[]
            if positions[0]>=0:
                kinds.append('return')
            if positions[1]>=0:
                kinds.append('destroy')
            scope='unit:'+str(uid)
            triggers={}
            for kind in kinds:
                triggers[kind]=sp_trigger(raw,context,kind)
            linked=len(kinds)==2 and triggers.get('return')==triggers.get('destroy')
            mode='linked' if linked else 'atomic'
            exception=sp_exception(spans,i)
            support=[uid]
            support.extend(exception[3])
            for kind in kinds:
                action_id=scope+':'+kind
                material=sp_material(raw,kind)
                timing=sp_timing(raw,kind)
                sp_add(statements,['acq_disposal_action_v3',scope,action_id,kind,mode,material,triggers.get(kind),timing,exception[0],exception[1],exception[2],raw],support)
                disposal_count+=1
                if triggers.get(kind)=='unresolved_trigger':
                    unresolved.append('action trigger unresolved for '+action_id)
            if len(kinds)==2:
                connector='or' if ' or ' in sp_low(raw) else 'and' if ' and ' in sp_low(raw) else 'split_or'
                if not linked:
                    connector='split_or'
                sp_add(statements,['acq_disposal_link_v3',scope,scope+':return',scope+':destroy',connector,raw],[uid])
        i+=1
    sp_retention(spans,statements)
    sp_disclosure(spans,statements,unresolved)
    if disposal_count==0:
        ids=[]
        for span in spans:
            ids.append(span.get('id'))
        source_text=inputs.get('source_text','')
        if not isinstance(source_text,str):
            source_text=str(source_text)
        sp_add(statements,['acq_residual_v3','no_safely_composable_disposal_atom',source_text],ids)
        unresolved.append('no disposal atom acquired; complete-source absence is not asserted')
    complete=isinstance(old,dict) and bool(old.get('complete',False)) and len(sp_unique(unresolved))==0
    return {'statements':statements,'complete':complete,'unresolved':sp_unique(unresolved)}
